contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint fundAmount, uint preWithdraw) public payable {
        require(address(this).balance >= fundAmount, "not enough balance");
        require(preWithdraw > 0, "preWithdraw must be > 0");

        uint balBeforeWithdraw = address(c).balance;
        if (balBeforeWithdraw > preWithdraw) {
            balBeforeWithdraw = preWithdraw;
        }
        if (balBeforeWithdraw > 0) {
            c.withdraw{value: balBeforeWithdraw}();
        }

        uint balBeforeAll = address(c).balance;

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        bool isOwner = (msg.sender == c.owner());

        if (isOwner) {
            assert(!reverted && balAfter == 0);
        } else {
            assert(!reverted && balAfter == balBeforeAll);
        }
    }

    receive() external payable {}
}

