        uint afterDeposits = c.depositsCount();

        assert(
            (afterDeposits == beforeDeposits) &&
            (reverted ? afterBalance == beforeBalance : (receivedBack == beforeBalance - afterBalance))
        );
    }

    fallback() external payable {
        receivedBack += msg.value;
    }
}

